import os
import tokenize

root = os.path.abspath('.')
results = []

for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d not in ('.git', '__pycache__')]
    for name in filenames:
        if not name.endswith('.py'):
            continue
        path = os.path.join(dirpath, name)
        try:
            with tokenize.open(path) as f:
                for tok in tokenize.generate_tokens(f.readline):
                    if tok.type == tokenize.COMMENT and 'TODO' in tok.string:
                        rel = os.path.relpath(path, root).replace(os.sep, '/')
                        results.append((rel, tok.start[0]))
        except (tokenize.TokenError, SyntaxError, UnicodeDecodeError, OSError):
            continue

results.sort(key=lambda item: (item[0], item[1]))
with open('todos.txt', 'w', encoding='utf-8') as out:
    for rel, line in results:
        out.write(rel + ':' + str(line) + '\n')
